/** CpfSmsAutoConfiguration 타입의 역할과 책임을 정의하며 CPF 계약 경계를 명확히 유지한다. */
package com.cpf.notification.dispatch.sms.spi;import com.cpf.notification.dispatch.CpfNotificationProvider;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.ConditionalOnBean;import org.springframework.context.annotation.Bean;@AutoConfiguration @ConditionalOnBean(CpfSmsProvider.class) public class CpfSmsAutoConfiguration {@Bean CpfSmsDispatcher cpfSmsDispatcher(CpfSmsProvider p){return new CpfSmsDispatcher(p);}@Bean CpfNotificationProvider cpfSmsNotificationAdapter(CpfSmsDispatcher d){return new CpfSmsNotificationAdapter(d);}}
